const ISSUE_DELETE_MASTER_ROLES=Object.freeze(["INTEGRATED_OWNER","PLATFORM_OWNER"]);
export function issueDeleteDecision({roleCodes=[],userId,createdByUserId,withinWindow=false}){const role=ISSUE_DELETE_MASTER_ROLES.find(value=>roleCodes.includes(value))||null;if(role)return {allowed:true,reason:"MASTER_DELETE",role};if(userId===createdByUserId&&withinWindow)return {allowed:true,reason:"USER_WITHIN_10_MINUTES",role:null};return {allowed:false,reason:"ISSUE_DELETE_NOT_ALLOWED",role:null}}
const isDynamicOrCustomCode=code=>String(code||"").startsWith("DYNAMIC_")||String(code||"").startsWith("CUSTOM_");
const isIssueBuildingFormPresetHidden=(row)=>{
  if(row.location_type!=="BUILDING") return false;
  if(isDynamicOrCustomCode(row.code)) return false;
  if(new Set(["BUILDING_1","BUILDING_2","BUILDING_3","BUILDING_4","BUILDING_5","BUILDING_6","BUILDING_7","BUILDING_8","BUILDING_9","BUILDING_10","BUILDING_11","BUILDING_12","BUILDING_13","BUILDING_14","BUILDING_15"]).has(row.code)) return true;
  return false;
};
const isIssueRoomFormPresetHidden=(row)=>{
  if(row.location_type!=="ROOM") return false;
  if(isDynamicOrCustomCode(row.code)) return false;
  if(row.code==="ROOM_ALL"||String(row.display_name||"").trim()==="전체") return true;
  if(new Set(["ENTRANCE","LIVING","KITCHEN","BEDROOM_1","BEDROOM_2","BEDROOM_3","BEDROOM_4","MASTER_BATH","COMMON_BATH","BATH_1","BATH_2","BALCONY","UTILITY","DRESS_ROOM"]).has(row.code)) return true;
  return false;
};
