const engineCoreEnabled=env=>env.ENGINE_CORE_ENABLED==="true";
async function refreshDepartmentRecommendation(env,issue,actorUserId,request,eventType=ENGINE_EVENTS.MANUAL_REQUEST){let result,executionId=null;if(engineCoreEnabled(env)){const sdk=createEngineSdk({db:env.DB,onError:(stage,error)=>console.error(`ENGINE_CORE_${stage}`,error)}),context=await constructionEvaluationContext({env,issue,eventType,actorUserId,operationId:eventType===ENGINE_EVENTS.MANUAL_REQUEST?(request.headers.get("idempotency-key")||requestId(request)):null}),evaluation=await sdk.evaluate(CONSTRUCTION_DEPARTMENT_ENGINE,context);result=evaluation.value;executionId=evaluation.executionId}else result=await recommendIssueDepartment(env,issue);try{await persistRecommendationSnapshot(env,issue,result,executionId);await auditStatement(env,actorUserId,result.engineError?"ISSUE_DEPARTMENT_RECOMMENDATION_FAILED":"ISSUE_DEPARTMENT_RECOMMENDED","ALLOWED",requestId(request),{issueId:issue.id,siteId:issue.site_id,recommendedDepartment:result.departmentCode,confidence:result.confidence,ruleIds:result.ruleIds,inputHash:result.inputHash,conflict:result.conflict}).run()}catch{try{await auditStatement(env,actorUserId,"ISSUE_DEPARTMENT_RECOMMENDATION_FAILED","DENIED",requestId(request),{issueId:issue.id,siteId:issue.site_id,inputHash:result.inputHash}).run()}catch{}}return result}
