async function photoFromForm(form){const photo=form.get("photo"),thumbnail=form.get("thumbnail");if(!(photo instanceof File)||!(thumbnail instanceof File))throw new ApiError(400,"ISSUE_PHOTO_REQUIRED","Original photo and thumbnail are required.");if(!IMAGE_TYPES.has(photo.type)||!IMAGE_TYPES.has(thumbnail.type))throw new ApiError(415,"ISSUE_PHOTO_TYPE_INVALID","JPG, PNG, and WebP are allowed.");if(photo.size<=0||photo.size>MAX_ORIGINAL)throw new ApiError(413,"ISSUE_PHOTO_TOO_LARGE","Original photo must be 12MB or less.");if(thumbnail.size<=0||thumbnail.size>MAX_THUMBNAIL)throw new ApiError(413,"ISSUE_THUMBNAIL_TOO_LARGE","Thumbnail must be 700KB or less.");return {photo,thumbnail}}
async function photosFromForm(form){const legacy=form.get("photo");if(legacy instanceof File)return [{...await photoFromForm(form),sortOrder:0}];const count=Number(form.get("photoCount"));if(!Number.isInteger(count)||count<1)throw new ApiError(400,"ISSUE_PHOTO_REQUIRED","At least one photo is required.");if(count>MAX_ISSUE_MEDIA)throw new ApiError(400,"ISSUE_PHOTO_LIMIT","한 이슈에는 최대 10장까지 등록할 수 있습니다.");const pairs=[];for(let index=0;index<count;index++){const photo=form.get(`photo_${index}`),thumbnail=form.get(`thumbnail_${index}`);if(!(photo instanceof File)||!(thumbnail instanceof File))throw new ApiError(400,"ISSUE_PHOTO_PAIR_INVALID","사진과 썸네일 순서를 다시 확인해 주세요.");const scoped=new FormData();scoped.set("photo",photo);scoped.set("thumbnail",thumbnail);pairs.push({...await photoFromForm(scoped),sortOrder:index})}return pairs}
async function storeMedia(env,{issueId,actionId=null,siteId,userId,role,photo,thumbnail,sortOrder=0,failureMode=null}){const mediaId=crypto.randomUUID(),safeName=String(photo.name||"photo").replace(/[^a-zA-Z0-9._-]/g,"_"),prefix=`sites/${siteId}/issues/${issueId}/${role.toLowerCase()}/${mediaId}`,originalKey=`${prefix}/original/${safeName}`,thumbnailKey=`${prefix}/thumbnail/${safeName}`,uploaded=[];try{if(failureMode==="ORIGINAL")throw new Error("E2E_ORIGINAL_FAILURE");await env.FILES.put(originalKey,photo.stream(),{httpMetadata:{contentType:photo.type},customMetadata:{siteId,issueId,mediaId,variant:"original"}});uploaded.push(originalKey);if(failureMode==="THUMBNAIL")throw new Error("E2E_THUMBNAIL_FAILURE");await env.FILES.put(thumbnailKey,thumbnail.stream(),{httpMetadata:{contentType:thumbnail.type},customMetadata:{siteId,issueId,mediaId,variant:"thumbnail"}});uploaded.push(thumbnailKey)}catch(error){await Promise.allSettled(uploaded.map(key=>env.FILES.delete(key)));throw new ApiError(502,"ISSUE_MEDIA_UPLOAD_FAILED","Issue media upload failed and partial objects were removed.")}return {mediaId,actionId,originalKey,thumbnailKey,name:photo.name||"photo",mime:photo.type,originalSize:photo.size,thumbnailSize:thumbnail.size,sortOrder,cleanup:()=>Promise.allSettled([env.FILES.delete(originalKey),env.FILES.delete(thumbnailKey)])}}
