 const where=`i.site_id=?1 AND (?2 IS NULL OR i.status=?2 OR (?2='UNHANDLED' AND i.status IN ('OPEN','ASSIGNED','ACTION_IN_PROGRESS','REWORK_REQUIRED'))) AND (?3 IS NULL OR i.trade_id=?3) AND (?4 IS NULL OR (?4='UNCLASSIFIED' AND dr.confirmed_department_code IS NULL) OR dr.confirmed_department_code=?4) AND (?5 IS NULL OR i.assigned_to_user_id=?5) AND (?6 IS NULL OR i.title LIKE ?6 ESCAPE '\\' OR i.description LIKE ?6 ESCAPE '\\' OR i.location_text LIKE ?6 ESCAPE '\\') AND (?7 IS NULL OR datetime(i.created_at)>=datetime(?7)) AND (?8 IS NULL OR datetime(i.created_at)<=datetime(?8)) AND (?9 IS NULL OR i.contractor_company_id=?9 OR i.created_by_user_id=?12) AND (?10 IS NULL OR i.assigned_to_user_id=?10 OR i.created_by_user_id=?12) AND (?11 IS NULL OR (?11='mine' AND i.assigned_to_user_id=?12 AND i.status NOT IN ('COMPLETED','CANCELLED')) OR (?11='urgent' AND i.priority='URGENT' AND i.status NOT IN ('COMPLETED','CANCELLED'))) AND (?13 IS NULL OR i.created_by_user_id=?13) AND (?14 IS NULL OR i.assignment_type=?14)`;
 const bindings=[auth.siteId,status,trade,department,assignee,pattern,dateFrom,dateTo,scopeCompany,scopeAssignee,view,auth.userId,scopeCreator,assignment],joins=" LEFT JOIN issue_department_recommendations dr ON dr.issue_id=i.id",rows=await env.DB.prepare(`SELECT i.*,(datetime(i.created_at)>=datetime('now','-10 minutes')) AS within_delete_window,c.name AS contractor_name,u.display_name AS assignee_name,tm.display_name trade_name,dr.recommended_department_code,dr.confidence department_confidence,dr.confidence_label department_confidence_label,dr.conflict department_conflict,dr.reason_json department_reason_json,dr.rule_ids_json department_rule_ids_json,dr.candidate_departments_json department_candidates_json,dr.evaluated_at department_evaluated_at,dr.confirmed_department_code,dr.confirmed_by_user_id,dr.confirmed_at,dr.manual_override department_manual_override,(SELECT thumbnail_key FROM issue_media m WHERE m.issue_id=i.id AND m.status='ACTIVE' AND m.media_role='CREATION' ORDER BY m.sort_order ASC,m.created_at ASC LIMIT 1) AS thumbnail_key,(SELECT COUNT(*) FROM issue_media mc WHERE mc.issue_id=i.id AND mc.media_role='CREATION' AND mc.status='ACTIVE') AS creation_media_count,(SELECT response FROM issue_assignee_responses r WHERE r.issue_id=i.id ORDER BY response_revision DESC,id DESC LIMIT 1) latest_response,(SELECT note FROM issue_assignee_responses r WHERE r.issue_id=i.id ORDER BY response_revision DESC,id DESC LIMIT 1) latest_response_note,(SELECT response_revision FROM issue_assignee_responses r WHERE r.issue_id=i.id ORDER BY response_revision DESC,id DESC LIMIT 1) latest_response_revision,(SELECT responded_at FROM issue_assignee_responses r WHERE r.issue_id=i.id ORDER BY response_revision DESC,id DESC LIMIT 1) latest_responded_at FROM issue_items i LEFT JOIN companies c ON c.id=i.contractor_company_id LEFT JOIN users u ON u.id=i.assigned_to_user_id LEFT JOIN trade_master tm ON tm.id=i.trade_id${joins} WHERE ${where} ORDER BY i.created_at DESC,i.id DESC LIMIT ?15 OFFSET ?16`).bind(...bindings,pageSize,offset).all(),count=await env.DB.prepare(`SELECT COUNT(*) AS count FROM issue_items i${joins} WHERE ${where}`).bind(...bindings).first();
 return json({issues:rows.results.map(row=>({...mapIssue(row,auth),thumbnailUrl:row.thumbnail_key?`/api/v1/issues/${row.id}/media/thumbnail`:null,creationMediaCount:Number(row.creation_media_count||0)})),page,pageSize,total:Number(count.count)})
